"""Build and publish a verifiable Redis Set intersection generation."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import socket
import sys


class RedisError(Exception):
    pass


class Client:
    def __init__(self, host, port):
        if host != '127.0.0.1' or not 1024 <= port <= 65535:
            raise ValueError('dedicated localhost high port required')
        self.socket = socket.create_connection((host, port), timeout=3)
        self.stream = self.socket.makefile('rb')

    def close(self):
        self.stream.close()
        self.socket.close()

    def command(self, *args):
        raw = [a if isinstance(a, bytes) else str(a).encode() for a in args]
        self.socket.sendall(('*%d\r\n' % len(raw)).encode() + b''.join(
            ('$%d\r\n' % len(a)).encode() + a + b'\r\n' for a in raw))
        return self.read()

    def read(self):
        line = self.stream.readline()
        if not line:
            raise ConnectionError('redis disconnected')
        tag, value = line[:1], line[1:-2]
        if tag == b'+':
            return value.decode()
        if tag == b'-':
            raise RedisError(value.decode())
        if tag == b':':
            return int(value)
        if tag == b'$':
            count = int(value)
            if count < 0:
                return None
            data = self.stream.read(count)
            if self.stream.read(2) != b'\r\n':
                raise ConnectionError('truncated RESP')
            return data.decode('utf-8')
        if tag == b'*':
            return None if int(value) < 0 else [self.read() for _ in range(int(value))]
        raise ConnectionError('bad RESP')


def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode()


def digest(value):
    return hashlib.sha256(canonical(value)).hexdigest()


ARTIFACT_NAMES = ('plan.json','result.json','audit.json','published.json')


def publish_bytes(path, data):
    # Publish by hard link: the final name is created atomically without replacing any winner.
    if path.is_symlink():
        raise ValueError('artifact symlink is not allowed')
    temporary = path.with_name(path.name + '.tmp-' + str(os.getpid()))
    try:
        with temporary.open('xb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            os.link(temporary, path, follow_symlinks=False)
        except FileExistsError:
            if path.is_symlink() or path.read_bytes() != data:
                raise ValueError('immutable artifact differs: ' + path.name)
    finally:
        temporary.unlink(missing_ok=True)


def write_new(path, value):
    publish_bytes(path, canonical(value) + b'\n')


def prepare_directory(root, generation):
    # A caller-supplied root alias denotes its real directory. Child aliases are never followed.
    root = Path(root).resolve()
    root.mkdir(parents=True, exist_ok=True)
    directory = root / generation
    if directory.is_symlink():
        raise ValueError('generation symlink is not allowed')
    directory.mkdir(exist_ok=True)
    if directory.resolve() != directory:
        raise ValueError('generation escapes root')
    for name in ARTIFACT_NAMES:
        if (directory / name).is_symlink():
            raise ValueError('artifact symlink is not allowed')
    return directory


def members(client, key):
    if client.command('TYPE', key) not in ('none', 'set'):
        raise ValueError('source must be Set or absent')
    return sorted(client.command('SMEMBERS', key))


def snapshot(client, keys):
    return {key: members(client, key) for key in keys}


def expected(plan):
    values = iter(plan['sources'].values())
    result = set(next(values))
    for values in values:
        result.intersection_update(values)
    return sorted(result)


def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument('phase', choices=['plan', 'materialize', 'promote'])
    parser.add_argument('--host', default='127.0.0.1')
    parser.add_argument('--port', required=True, type=int)
    parser.add_argument('--prefix', required=True)
    parser.add_argument('--generation', required=True)
    parser.add_argument('--root', required=True)
    parser.add_argument('--request')
    args = parser.parse_args(argv)
    if not re.fullmatch(r'of:[a-f0-9]{16,48}:', args.prefix):
        raise ValueError('dedicated prefix required')
    if not re.fullmatch(r'[a-z0-9_-]{1,32}', args.generation):
        raise ValueError('invalid generation')
    directory = prepare_directory(args.root, args.generation)
    client = Client(args.host, args.port)
    active = args.prefix + 'active'
    stage = args.prefix + args.generation + ':stage'
    marker = args.prefix + args.generation + ':published'
    try:
        if args.phase == 'plan':
            request = json.loads(Path(args.request).read_text(encoding='utf-8'))
            keys = request['sources']
            if (not isinstance(keys, list) or len(keys) < 2 or
                    any(not isinstance(k, str) or not k or k.startswith(args.prefix) for k in keys) or
                    len(set(keys)) != len(keys)):
                raise ValueError('distinct external source keys required')
            client.command('WATCH', *keys)
            sources = snapshot(client, keys)
            client.command('MULTI')
            client.command('PING')
            if client.command('EXEC') is None:
                raise ValueError('sources changed during planning')
            plan = {'schema': 1, 'generation': args.generation, 'prefix': args.prefix,
                    'sources': sources, 'source_sha256': digest(sources)}
            write_new(directory / 'plan.json', plan)
            print(json.dumps({'phase': 'plan', 'source_sha256': plan['source_sha256']}))
            return
        plan = json.loads((directory / 'plan.json').read_text(encoding='utf-8'))
        if (plan['generation'] != args.generation or plan['prefix'] != args.prefix or
                digest(plan['sources']) != plan['source_sha256'] or len(plan['sources']) < 2 or
                any(k.startswith(args.prefix) for k in plan['sources'])):
            raise ValueError('invalid plan')
        keys = list(plan['sources'])
        wanted = expected(plan)
        result = {'schema': 1, 'source_sha256': plan['source_sha256'],
                  'members': wanted, 'members_sha256': digest(wanted), 'count': len(wanted)}
        if args.phase == 'materialize':
            client.command('WATCH', *keys, stage, marker)
            if snapshot(client, keys) != plan['sources']:
                raise ValueError('source drift; prepare another generation')
            if client.command('EXISTS', marker):
                if members(client, stage) != wanted:
                    raise ValueError('published stage changed')
            else:
                client.command('MULTI')
                script = Path('task.lua').read_text(encoding='utf-8')
                client.command('EVAL', script, len(keys) + 1, stage, *keys)
                if client.command('EXEC') is None:
                    raise ValueError('concurrent change; retry')
                if members(client, stage) != wanted:
                    raise ValueError('native intersection differs')
            write_new(directory / 'result.json', result)
            write_new(directory / 'audit.json', {'operation': 'SINTERSTORE', 'stage': stage,
                                                'sources': keys, 'source_sha256': plan['source_sha256']})
            print(json.dumps({'phase': 'materialize', 'count': len(wanted)}))
            return
        if json.loads((directory / 'result.json').read_text(encoding='utf-8')) != result:
            raise ValueError('result artifact differs')
        if json.loads((directory / 'audit.json').read_text(encoding='utf-8')) != {
                'operation': 'SINTERSTORE', 'stage': stage, 'sources': keys,
                'source_sha256': plan['source_sha256']}:
            raise ValueError('audit artifact differs')
        client.command('WATCH', *keys, stage, marker, active)
        if snapshot(client, keys) != plan['sources'] or members(client, stage) != wanted:
            raise ValueError('source or stage drift')
        receipt = {'schema': 1, 'generation': args.generation,
                   'source_sha256': plan['source_sha256'], 'members_sha256': digest(wanted)}
        previous = client.command('GET', marker)
        if previous is not None:
            if json.loads(previous) != receipt:
                raise ValueError('published generation mismatch')
        else:
            # Validate all destination types before MULTI: Redis transactions do not roll back errors.
            if client.command('TYPE', active) not in ('none', 'set'):
                raise ValueError('active must be Set or absent')
            client.command('MULTI')
            client.command('SINTERSTORE', active, stage, stage)
            client.command('SET', marker, canonical(receipt))
            if client.command('EXEC') is None:
                raise ValueError('concurrent change; retry')
        # Redis EXEC is the commit point. Reporting errors afterwards do not claim rollback.
        write_new(directory / 'published.json', receipt)
        print(json.dumps({'phase': 'promote', 'committed': True, **receipt}))
    finally:
        client.close()


if __name__ == '__main__':
    try:
        main()
    except (ValueError, KeyError, TypeError, OSError, RedisError) as error:
        print(str(error), file=sys.stderr)
        raise SystemExit(2)

