class RedisError(Exception):
    pass


class Client:
    def __init__(self, host, port):
        if host != '127.0.0.1' or not 1024 <= port <= 65535:
            raise ValueError('dedicated localhost high port required')
        self.socket = socket.create_connection((host, port), timeout=3)
        self.stream = self.socket.makefile('rb')

    def close(self):
        self.stream.close()
        self.socket.close()

    def command(self, *args):
        raw = [a if isinstance(a, bytes) else str(a).encode() for a in args]
        self.socket.sendall(('*%d\r\n' % len(raw)).encode() + b''.join(
            ('$%d\r\n' % len(a)).encode() + a + b'\r\n' for a in raw))
        return self.read()

    def read(self):
        line = self.stream.readline()
        if not line:
            raise ConnectionError('redis disconnected')
        tag, value = line[:1], line[1:-2]
        if tag == b'+':
            return value.decode()
        if tag == b'-':
            raise RedisError(value.decode())
        if tag == b':':
            return int(value)
        if tag == b'$':
            count = int(value)
            if count < 0:
                return None
            data = self.stream.read(count)
            if self.stream.read(2) != b'\r\n':
                raise ConnectionError('truncated RESP')
            return data.decode('latin1')
        if tag == b'*':
            return None if int(value) < 0 else [self.read() for _ in range(int(value))]
        raise ConnectionError('bad RESP')


def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode()


def digest(value):
    return hashlib.sha256(canonical(value)).hexdigest()


ARTIFACT_NAMES = ('plan.json','result.json','audit.json','published.json','union.hll')


def publish_bytes(path, data):
    # Publish by hard link: the final name is created atomically without replacing any winner.
    if path.is_symlink():
        raise ValueError('artifact symlink is not allowed')
    temporary = path.with_name(path.name + '.tmp-' + str(os.getpid()))
    try:
        with temporary.open('xb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        try:
            os.link(temporary, path, follow_symlinks=False)
        except FileExistsError:
            if path.is_symlink() or path.read_bytes() != data:
                raise ValueError('immutable artifact differs: ' + path.name)
    finally:
        temporary.unlink(missing_ok=True)


def write_new(path, value):
    publish_bytes(path, canonical(value) + b'\n')


def prepare_directory(root, generation):
    # A caller-supplied root alias denotes its real directory. Child aliases are never followed.
    root = Path(root).resolve()
    root.mkdir(parents=True, exist_ok=True)
    directory = root / generation
    if directory.is_symlink():
        raise ValueError('generation symlink is not allowed')
    directory.mkdir(exist_ok=True)
    if directory.resolve() != directory:
        raise ValueError('generation escapes root')
    for name in ARTIFACT_NAMES:
        if (directory / name).is_symlink():
            raise ValueError('artifact symlink is not allowed')
    return directory


def hll(client, key):
    count = client.command('PFCOUNT', key)
    raw = client.command('GET', key)
    return {'blob': None if raw is None else base64.b64encode(raw.encode('latin1')).decode(),
            'estimate': count}


def snapshot(client, keys):
    return {key: hll(client, key) for key in keys}


def expected(plan, client, stage):
    temporary = [stage + ':oracle:' + str(i) for i in range(len(plan['sources']))]
    merged = stage + ':oracle:merged'
    try:
        for key, value in zip(temporary, plan['sources'].values()):
            client.command('DEL', key)
            if value['blob'] is not None:
                client.command('SET', key, base64.b64decode(value['blob'], validate=True))
        client.command('PFMERGE', merged, *temporary)
        return hll(client, merged)
    finally:
        client.command('DEL', merged, *temporary)


def result_for(plan, wanted):
    return {'schema': 1, 'source_sha256': plan['source_sha256'], 'approximate': True,
            'estimate': wanted['estimate'],
