def bits(ids, mapping):
    size = (len(mapping) + 7) // 8
    data = bytearray(size)
    for user in ids:
        offset = mapping[user]
        data[offset // 8] |= 1 << (7 - offset % 8)
    return bytes(data)


def derive(plan):
    mapping = dict(plan['base_state']['mapping'])
    universe = set(mapping)
    for cohort in plan['sources'].values():
        universe.update(cohort)
    universe.update(event['id'] for event in plan['events'])
    for user in sorted(universe - set(mapping)):
        mapping[user] = len(mapping)
    if len(mapping) > 4096 or set(mapping.values()) != set(range(len(mapping))):
        raise ValueError('mapping capacity or dense identity invariant')
    active, revoked = set(plan['base_state']['active']), set(plan['base_state']['revoked'])
    for event in plan['events']:
        user = event['id']
        if event['action'] == 'grant':
            active.add(user); revoked.discard(user)
        else:
            active.discard(user); revoked.add(user)
    cohorts = list(plan['sources'].values())
    selected = active & set(cohorts[0]) & set(cohorts[1])
    state = {'mapping': mapping, 'active': sorted(active), 'revoked': sorted(revoked)}
    payloads = {'active': bits(active, mapping), 'revoked': bits(revoked, mapping),
                'cohort_a': bits(cohorts[0], mapping), 'cohort_b': bits(cohorts[1], mapping),
                'selected': bits(selected, mapping), 'invariant': bytes((len(mapping)+7)//8)}
    result = {'schema': 1, 'source_sha256': digest(plan['sources']),
              'selected_ids': sorted(selected), 'count': len(selected),
              'bitmap_sha256': {k: hashlib.sha256(v).hexdigest() for k, v in payloads.items()}}
    audit = {'base': plan['base'], 'events': [dict(e, offset=mapping[e['id']]) for e in plan['events']],
             'max_offset': len(mapping)-1, 'source_sha256': digest(plan['sources'])}
    return state, payloads, result, audit


def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument('phase', choices=['build', 'promote'])
    parser.add_argument('--port', type=int, required=True)
    parser.add_argument('--prefix', required=True)
    parser.add_argument('--generation', required=True)
    parser.add_argument('--root', required=True)
    parser.add_argument('--request')
    args = parser.parse_args(argv)
    if not re.fullmatch(r'of:[a-f0-9]{16,48}:', args.prefix) or not re.fullmatch(r'[a-z0-9_-]{1,32}', args.generation):
        raise ValueError('invalid dedicated prefix or generation')
    directory = prepare_directory(args.root, args.generation)
    client = Client('127.0.0.1', args.port)
    head = args.prefix+'head'
    stage = args.prefix+args.generation+':'
    marker = stage+'published'
    try:
        if args.phase == 'build' and not (directory/'plan.json').exists():
            request = json.loads(Path(args.request).read_text(encoding='utf-8'))
            keys, events = request['cohorts'], request['events']
            if (not isinstance(keys, list) or len(keys) != 2 or
                    any(not isinstance(k, str) or not k or k.startswith(args.prefix) for k in keys) or
                    len(set(keys)) != 2 or not isinstance(events, list)):
                raise ValueError('two distinct external cohorts and events required')
            for event in events:
                if (not isinstance(event, dict) or set(event) != {'id', 'action'} or
                        not isinstance(event['id'], str) or not event['id'] or
                        event['action'] not in ('grant', 'revoke')):
                    raise ValueError('invalid membership event')
            client.command('WATCH', head, *keys)
            base = client.command('GET', head)
            state = {'mapping': {}, 'active': [], 'revoked': []} if base is None else json.loads(
                client.command('GET', args.prefix+base+':state'))
            sources = snapshot(client, keys)
            client.command('MULTI');client.command('PING')
            if client.command('EXEC') is None:
                raise ValueError('concurrent input change')
            plan = {'schema': 1, 'generation': args.generation, 'prefix': args.prefix, 'base': base,
                    'base_state': state, 'sources': sources, 'events': events}
            derive(plan)  # Validate capacity and entire request before any Redis stage writes.
            write_new(directory/'plan.json', plan)
        plan = json.loads((directory/'plan.json').read_text(encoding='utf-8'))
        if plan['generation'] != args.generation or plan['prefix'] != args.prefix:
            raise ValueError('generation mismatch')
        state, payloads, result, audit = derive(plan)
        keys = list(plan['sources'])
        if args.phase == 'build':
            if args.request is not None:
                request = json.loads(Path(args.request).read_text(encoding='utf-8'))
                if (not isinstance(request.get('cohorts'), list) or set(request['cohorts']) != set(keys) or len(request['cohorts']) != 2 or request.get('events') != plan['events']):
                    raise ValueError('immutable request differs')
            client.command('WATCH', *keys, head, marker)
            if snapshot(client, keys) != plan['sources']:
                raise ValueError('source drift')
            if client.command('EXISTS', marker):
                if any((client.command('GET', stage+k) or '').encode('latin1') != v for k,v in payloads.items()):
                    raise ValueError('published bitmap changed')
            else:
                if client.command('GET', head) != plan['base']:
                    raise ValueError('base changed')
                client.command('MULTI')
                for name in payloads:
                    client.command('SET', stage+name, bytes(len(payloads[name])))
                client.command('SET', stage+'active', bits(plan['base_state']['active'],state['mapping']))
                client.command('SET', stage+'revoked', bits(plan['base_state']['revoked'],state['mapping']))
                script = Path('task.lua').read_text(encoding='utf-8')
                for event in plan['events']:
                    client.command('EVAL', script, 3, stage+'active',stage+'revoked',stage+'invariant',
                                   state['mapping'][event['id']],event['action'])
                for index, name in enumerate(('cohort_a','cohort_b')):
                    for user in plan['sources'][keys[index]]:
                        client.command('SETBIT',stage+name,state['mapping'][user],1)
                client.command('BITOP','AND',stage+'selected',stage+'active',stage+'cohort_a',stage+'cohort_b')
                if client.command('EXEC') is None:
                    raise ValueError('concurrent input change')
                if any((client.command('GET',stage+k) or '').encode('latin1') != v for k,v in payloads.items()):
                    raise ValueError('native bitmap differs')
            write_new(directory/'mapping.json',state['mapping'])
            write_new(directory/'result.json',result)
            write_new(directory/'audit.json',audit)
            print(json.dumps({'phase':'build','count':result['count']}))
            return
        for filename, value in [('mapping.json',state['mapping']),('result.json',result),('audit.json',audit)]:
            if json.loads((directory/filename).read_text(encoding='utf-8')) != value:
                raise ValueError('artifact differs')
        client.command('WATCH',head,marker,*keys,*(stage+k for k in payloads))
        if snapshot(client,keys) != plan['sources'] or any(
                (client.command('GET',stage+k) or '').encode('latin1') != v for k,v in payloads.items()):
            raise ValueError('source or stage drift')
        receipt = {'schema':1,'generation':args.generation,'base':plan['base'],'result_sha256':digest(result)}
        previous = client.command('GET',marker)
        if previous is not None:
            if json.loads(previous) != receipt:
                raise ValueError('published receipt differs')
        else:
            if client.command('GET',head) != plan['base']:
                raise ValueError('stale base')
            client.command('MULTI')
            client.command('SET',stage+'state',canonical(state))
            client.command('SET',head,args.generation)
            client.command('SET',marker,canonical(receipt))
            if client.command('EXEC') is None:
                raise ValueError('concurrent change')
        write_new(directory/'published.json',receipt)
        print(json.dumps({'phase':'promote','committed':True,**receipt}))
    finally:
        client.close()


if __name__ == '__main__':
    try:
        main()
    except (ValueError,KeyError,TypeError,OSError,RedisError) as error:
        print(str(error),file=sys.stderr)
        raise SystemExit(2)

